              "{\"headline\":\"Treasury Secretary Mnuchin says US and China have agreed on the trade deal enforcement mechanism\",\"dateCreated\":\"2019-04-10T17:36:32+0000\",\"datePublished\":\"2019-04-10T17:36:32+0000\",\"dateModified\":\"2019-04-10T19:39:05+0000\",\"author\":[{\"name\":\"Yun Li\"}],\"publisher\":{\"name\":\"CNBC\",\"foundingDate\":\"1989-04-17\",\"sameAs\":[\"https://www.facebook.com/cnbc\",\"https://www.instagram.com/cnbc\",\"https://www.linkedin.com/company/cnbc\",\"https://twitter.com/cnbc\",\"https://en.wikipedia.org/wiki/CNBC\",\"https://www.youtube.com/cnbc\"]},\"articleSection\":\"Markets\",\"keywords\":[\"cnbc\",\"Articles\",\"Sara Eisen\",\"Politics\",\"Steven Mnuchin\",\"Breaking News: Markets\",\"Breaking News: Investing\",\"Breaking News: Business\",\"Investment strategy\",\"Wall Street\",\"Stock markets\",\"Markets\",\"U.S. Markets\",\"stocks\",\"Finance\",\"Investing\",\"source:tagname:CNBC US Source\"],\"video\":{\"description\":\"CNBC's Sara Eisen sits down with Treasury Secretary Steven Mnuchin to discuss the latest in the on-going U.S.-China trade negotiations.\",\"duration\":\"PT2M23S\",\"name\":\"Mnuchin: US-China trade deal would be the most significant in decades\",\"uploadDate\":\"2019-04-10T17:47:43+0000\"}}"
